      "text": "После разоблачения в растрате Питер Виллемс получает от капитана Лингарда возможность начать заново на отдалённой речной фактории. Любовное увлечение втягивает его в местное соперничество и ставит перед выбором между благодарностью спасителю и предательством его доверия.",
