      "text": "Том и Тоби бегут с китобойного судна на острове Нуку-Хива и находят приют у его жителей. Гостеприимство не избавляет их от тревоги: зависимость от незнакомого сообщества заставляет заново разбираться в границе между безопасностью, свободой и собственными предубеждениями.",
