      "text": "Во время очередного приезда в шотландский Круден-Бей рассказчик сталкивается со странной старухой и тревожными событиями на морском берегу. Знакомство с Марджори вовлекает его в работу над тайными письменами, соединяя личное увлечение с поиском смысла в знаках, которые сначала кажутся непонятными.",
